                  const make = (start: number) => (tooth: { fdi: number }) => { const d = (arcDepth ?? current.arcUsed ?? 1) - start; return Math.abs(d) < 1e-6 ? null : tooth.fdi % 10 === 3 ? { up: -d } : tooth.fdi % 10 === 2 ? { up: -d / 2 } : null; };
